/// Binary search helper returning the lower bound index k in [lo, hi)
/// such that:
/// - for all r in [lo, k), a[r] < x
/// - for all r in [k, hi), a[r] >= x
fn search_range_helper(a: &[i32], x: i32, lo: usize, hi: usize) -> usize {
    // lo and hi define a range in a where a[lo..hi] is sorted nondecreasing
    let mut left = lo;
    let mut right = hi;

    while left < right {
        let mid = left + (right - left) / 2;
        if a[mid] < x {
            left = mid + 1;
        } else {
            right = mid;
        }
    }
    // left == right is the insertion position k
    left
}

